import math

def get_order(base, modulus):
    if math.gcd(base, modulus) != 1:
        return None

    # Euler's totient function phi(n)
    def phi(n):
        result = n
        p = 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result

    phi_n = phi(modulus)

    # Find prime factors of phi(modulus)
    factors = set()
    n = phi_n
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.add(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.add(n)

    # Test divisors of phi_n
    order = phi_n
    for p in factors:
        while order % p == 0 and pow(base, order // p, modulus) == 1:
            order //= p
    return order

# Calculate the order of 3 modulo 10000
L = get_order(3, 10000)
print(f"L = {L}")

import math
from sympy import mod_inverse, gcd

def order(a, n):
    """Calculates the multiplicative order of a modulo n."""
    if math.gcd(a, n) != 1:
        return None

    # Euler's totient function phi(n)
    phi = n
    temp_n = n
    i = 2
    while i * i <= temp_n:
        if temp_n % i == 0:
            phi = phi // i * (i - 1)
            while temp_n % i == 0:
                temp_n //= i
        i += 1
    if temp_n > 1:
        phi = phi // temp_n * (temp_n - 1)

    # Find prime factorization of phi
    factors = []
    d = 2
    temp_phi = phi
    while d * d <= temp_phi:
        if temp_phi % d == 0:
            factors.append(d)
            while temp_phi % d == 0:
                temp_phi //= d
        d += 1
    if temp_phi > 1:
        factors.append(temp_phi)

    # Test divisors of phi
    for p in factors:
        divisor = phi // p
        while math.gcd(divisor, phi) != 1:
             divisor = divisor // p # should not happen if factors are prime

        if pow(a, divisor, n) == 1:
            return divisor

    return phi # Should return phi if no smaller order is found (only if phi is prime, which is unlikely)

# Calculate order mod 625
order_625 = order(3, 625)
print(f"Order of 3 mod 625: {order_625}")

